{"version":3,"file":"ops-app.jsdbx","sources":["../../src/client/ops-app.tsx","../../src/client/ops-app.css"],"sourcesContent":["import React, { useState, useEffect } from 'react';
import NavHeader from './components/shared/NavHeader';
import './ops-app.css';

/*
 * Operations Dashboard — DarkOps
 * All KPI numbers are hardcoded to match spec exactly.
 * In production these would come from Table API calls.
 */

/* --- Page Header with Live Timer --- */
function OpsPageHeader() {
  const [seconds, setSeconds] = useState(14);

  useEffect(() => {
    const interval = setInterval(() => {
      setSeconds((s) => s + 1);
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="ops-page-header">
      <div>
        <h1 className="ops-page-header__title">Operations queue</h1>
        <p className="ops-page-header__subtitle">Shift 2 (14:00–22:00 IST) · 500 agents on roster</p>
      </div>
      <span className="ops-page-header__live-pill">
        <span className="ops-page-header__live-dot" />
        Updated {seconds}s ago · LIVE
      </span>
    </div>
  );
}

/* --- KPI Row --- */
function KpiRow() {
  return (
    <div className="ops-kpi-row">
      <div className="ops-kpi-card">
        <span className="ops-kpi-card__label">PENDING CASES</span>
        <span className="ops-kpi-card__value">1,342</span>
        <p className="ops-kpi-card__caption">open across all hubs</p>
      </div>

      <div className="ops-kpi-card">
        <span className="ops-kpi-card__label">ESCALATED CASES</span>
        <span className="ops-kpi-card__value">186</span>
        <p className="ops-kpi-card__caption">L2 / regional manager</p>
      </div>

      <div className="ops-kpi-card ops-kpi-card--red">
        <span className="ops-kpi-card__label">
          <span className="ops-kpi-card__label-icon">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
              <path d="M12 2L1 21h22L12 2z" fill="none" stroke="#ef4444" strokeWidth="2" strokeLinejoin="round" />
              <path d="M12 9v4" stroke="#ef4444" strokeWidth="2" strokeLinecap="round" />
              <circle cx="12" cy="17" r="1" fill="#ef4444" />
            </svg>
          </span>
          SLA BREACHES TODAY
        </span>
        <span className="ops-kpi-card__value ops-kpi-card__value--red">74</span>
        <p className="ops-kpi-card__caption">past 2h response SLA</p>
      </div>

      <div className="ops-kpi-card">
        <span className="ops-kpi-card__label">AGENTS AVAILABLE</span>
        <span className="ops-kpi-card__value">138</span>
        <p className="ops-kpi-card__caption">of 500 on shift<br />idle or under 60% load</p>
      </div>

      <div className="ops-kpi-card">
        <span className="ops-kpi-card__label">AWAITING ASSIGNMENT</span>
        <span className="ops-kpi-card__value">212</span>
        <p className="ops-kpi-card__caption">oldest waiting 47m</p>
      </div>
    </div>
  );
}

/* --- Donut Chart (SVG) --- */
function PriorityDonutChart() {
  const data = [
    { label: 'P1 Critical', value: 148, color: '#ef4444' },
    { label: 'P2 High', value: 386, color: '#f59e0b' },
    { label: 'P3 Medium', value: 562, color: '#3b82f6' },
    { label: 'P4 Low', value: 246, color: '#64748b' },
  ];

  const total = data.reduce((sum, d) => sum + d.value, 0);
  const cx = 80;
  const cy = 80;
  const outerRadius = 70;
  const innerRadius = 44;

  let cumulativeAngle = -90;

  const segments = data.map((d) => {
    const angle = (d.value / total) * 360;
    const startAngle = cumulativeAngle;
    const endAngle = cumulativeAngle + angle;
    cumulativeAngle = endAngle;

    const startRad = (startAngle * Math.PI) / 180;
    const endRad = (endAngle * Math.PI) / 180;

    const x1Outer = cx + outerRadius * Math.cos(startRad);
    const y1Outer = cy + outerRadius * Math.sin(startRad);
    const x2Outer = cx + outerRadius * Math.cos(endRad);
    const y2Outer = cy + outerRadius * Math.sin(endRad);
    const x1Inner = cx + innerRadius * Math.cos(endRad);
    const y1Inner = cy + innerRadius * Math.sin(endRad);
    const x2Inner = cx + innerRadius * Math.cos(startRad);
    const y2Inner = cy + innerRadius * Math.sin(startRad);

    const largeArc = angle > 180 ? 1 : 0;

    const path = [
      `M ${x1Outer} ${y1Outer}`,
      `A ${outerRadius} ${outerRadius} 0 ${largeArc} 1 ${x2Outer} ${y2Outer}`,
      `L ${x1Inner} ${y1Inner}`,
      `A ${innerRadius} ${innerRadius} 0 ${largeArc} 0 ${x2Inner} ${y2Inner}`,
      'Z',
    ].join(' ');

    return { ...d, path };
  });

  return (
    <div className="ops-card">
      <div className="ops-card__header">
        <div>
          <h3 className="ops-card__title">Complaint priority mix</h3>
          <p className="ops-card__subtitle">All 1,342 pending cases, split by priority.</p>
        </div>
      </div>
      <div className="ops-donut">
        <svg width="160" height="160" viewBox="0 0 160 160">
          {segments.map((seg) => (
            <path key={seg.label} d={seg.path} fill={seg.color} />
          ))}
        </svg>
        <div className="ops-donut__legend">
          {data.map((d) => (
            <span className="ops-donut__legend-item" key={d.label}>
              <span className="ops-donut__legend-dot" style={{ background: d.color }} />
              {d.label}
              <span className="ops-donut__legend-value">— {d.value}</span>
            </span>
          ))}
        </div>
      </div>
    </div>
  );
}

/* --- Horizontal Bar Chart --- */
function PendingStatusChart() {
  const bars = [
    { label: 'Unassigned', value: 212 },
    { label: 'Assigned', value: 480 },
    { label: 'In progress', value: 550 },
    { label: 'Awaiting customer', value: 150 },
  ];

  const xMax = 600;

  return (
    <div className="ops-card">
      <div className="ops-card__header">
        <div>
          <h3 className="ops-card__title">Pending case status</h3>
          <p className="ops-card__subtitle">Same 1,342 cases by stage · 212 still unassigned.</p>
        </div>
      </div>
      <div className="ops-hbar">
        {bars.map((bar) => (
          <div className="ops-hbar__row" key={bar.label}>
            <span className="ops-hbar__label">{bar.label}</span>
            <div className="ops-hbar__track">
              <div
                className="ops-hbar__fill"
                style={{ width: `${(bar.value / xMax) * 100}%` }}
              />
            </div>
            <span className="ops-hbar__value">{bar.value}</span>
          </div>
        ))}
        <div className="ops-hbar__axis">
          <span className="ops-hbar__axis-label">0</span>
          <span className="ops-hbar__axis-label">150</span>
          <span className="ops-hbar__axis-label">300</span>
          <span className="ops-hbar__axis-label">450</span>
          <span className="ops-hbar__axis-label">600</span>
        </div>
      </div>
    </div>
  );
}

/* --- Vertical Bar Chart --- */
function AgentWorkloadChart() {
  const hubs = [
    { name: 'Bengaluru', value: 190 },
    { name: 'Mumbai', value: 230 },
    { name: 'Delhi NCR', value: 200 },
    { name: 'Chennai', value: 140 },
    { name: 'Night Shift', value: 70 },
  ];

  const yMax = 280;
  const yTicks = [0, 70, 140, 210, 280];

  return (
    <div className="ops-card">
      <div className="ops-card__header">
        <div>
          <h3 className="ops-card__title">Agent workload by hub</h3>
          <p className="ops-card__subtitle">Assigned + in-progress cases (998) vs hub capacity.</p>
        </div>
      </div>
      <div className="ops-vbar">
        <div className="ops-vbar__y-axis">
          {yTicks.slice().reverse().map((t) => (
            <span key={t} className="ops-vbar__y-label">{t}</span>
          ))}
        </div>
        <div className="ops-vbar__bars">
          {hubs.map((hub) => (
            <div className="ops-vbar__col" key={hub.name}>
              <div className="ops-vbar__bar-wrap">
                <div
                  className="ops-vbar__bar"
                  style={{ height: `${(hub.value / yMax) * 100}%` }}
                />
              </div>
              <span className="ops-vbar__x-label">{hub.name}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

/* --- Queue Data --- */
interface QueueRow {
  id: string;
  description: string;
  storeName: string;
  storeCity: string;
  storeId: string;
  priority: 'P1' | 'P2' | 'P3' | 'P4';
  agent: string;
  agentId: string;
  status: string;
  age: string;
  ageMinutes: number;
}

const QUEUE_DATA: QueueRow[] = [
  { id: 'CMP-482000', description: 'Order delivered 46 min late', storeName: 'Chennai Old City DS, Chennai', storeCity: 'Chennai', storeId: 'DS-1770', priority: 'P2', agent: 'Unassigned', agentId: '', status: 'Unassigned', age: '2h 46m', ageMinutes: 166 },
  { id: 'CMP-482137', description: 'Melted frozen goods on arrival', storeName: 'Chandigarh North DS, Chandigarh', storeCity: 'Chandigarh', storeId: 'DS-1070', priority: 'P3', agent: 'A. Verma', agentId: 'AG-0917', status: 'Awaiting customer', age: '3h 39m', ageMinutes: 219 },
  { id: 'CMP-482274', description: 'Rider marked delivered, not received', storeName: 'Kolkata Riverside DS, Kolkata', storeCity: 'Kolkata', storeId: 'DS-2092', priority: 'P1', agent: 'M. Fernandes', agentId: 'AG-2760', status: 'Escalated — L2', age: '0h 13m', ageMinutes: 13 },
  { id: 'CMP-482411', description: 'Order delivered 46 min late', storeName: 'Kochi Airport Road DS, Kochi', storeCity: 'Kochi', storeId: 'DS-1714', priority: 'P3', agent: 'R. Iyer', agentId: 'AG-2041', status: 'Assigned', age: '3h 18m', ageMinutes: 198 },
  { id: 'CMP-482548', description: 'Melted frozen goods on arrival', storeName: 'Hyderabad South DS, Hyderabad', storeCity: 'Hyderabad', storeId: 'DS-1126', priority: 'P4', agent: 'R. Iyer', agentId: 'AG-2041', status: 'Escalated — L2', age: '0h 32m', ageMinutes: 32 },
  { id: 'CMP-482685', description: 'Wrong item substituted', storeName: 'Mumbai North DS, Mumbai', storeCity: 'Mumbai', storeId: 'DS-1007', priority: 'P4', agent: 'Unassigned', agentId: '', status: 'Unassigned', age: '3h 13m', ageMinutes: 193 },
  { id: 'CMP-482822', description: 'Expired product delivered', storeName: 'Bengaluru South DS, Bengaluru', storeCity: 'Bengaluru', storeId: 'DS-1105', priority: 'P4', agent: 'A. Verma', agentId: 'AG-0917', status: 'Assigned', age: '2h 36m', ageMinutes: 156 },
  { id: 'CMP-482959', description: 'Wrong item substituted', storeName: 'Bengaluru Airport Road DS, Bengaluru', storeCity: 'Bengaluru', storeId: 'DS-1630', priority: 'P3', agent: 'K. Reddy', agentId: 'AG-1502', status: 'Escalated — L2', age: '2h 55m', ageMinutes: 175 },
  { id: 'CMP-483096', description: 'Rider marked delivered, not received', storeName: 'Kolkata Riverside DS, Kolkata', storeCity: 'Kolkata', storeId: 'DS-2092', priority: 'P3', agent: 'R. Iyer', agentId: 'AG-2041', status: 'Escalated — L2', age: '4h 11m', ageMinutes: 251 },
  { id: 'CMP-483233', description: 'Wrong item substituted', storeName: 'Mumbai Riverside DS, Mumbai', storeCity: 'Mumbai', storeId: 'DS-2057', priority: 'P3', agent: 'M. Fernandes', agentId: 'AG-2760', status: 'In progress', age: '5h 34m', ageMinutes: 334 },
  { id: 'CMP-483370', description: 'Order delivered 46 min late', storeName: 'Hyderabad Outer Ring DS, Hyderabad', storeCity: 'Hyderabad', storeId: 'DS-1966', priority: 'P2', agent: 'Unassigned', agentId: '', status: 'Unassigned', age: '2h 47m', ageMinutes: 167 },
  { id: 'CMP-483507', description: 'Wrong item substituted', storeName: 'Delhi NCR Outer Ring DS, Delhi NCR', storeCity: 'Delhi NCR', storeId: 'DS-1959', priority: 'P4', agent: 'A. Verma', agentId: 'AG-0917', status: 'In progress', age: '3h 56m', ageMinutes: 236 },
  { id: 'CMP-483644', description: 'Partial order cancelled at pack', storeName: 'Delhi NCR Industrial Belt DS, Delhi NCR', storeCity: 'Delhi NCR', storeId: 'DS-2169', priority: 'P2', agent: 'R. Iyer', agentId: 'AG-2041', status: 'In progress', age: '0h 24m', ageMinutes: 24 },
  { id: 'CMP-483781', description: 'Order delivered 46 min late', storeName: 'Hyderabad IT Corridor DS, Hyderabad', storeCity: 'Hyderabad', storeId: 'DS-1861', priority: 'P3', agent: 'A. Verma', agentId: 'AG-0917', status: 'Awaiting customer', age: '2h 43m', ageMinutes: 163 },
];

function getAgeClass(minutes: number): string {
  if (minutes < 60) return 'ops-queue__age--fresh';
  if (minutes <= 180) return 'ops-queue__age--risk';
  return 'ops-queue__age--overdue';
}

function getPriorityClass(p: string): string {
  switch (p) {
    case 'P1': return 'ops-queue__priority--p1';
    case 'P2': return 'ops-queue__priority--p2';
    case 'P3': return 'ops-queue__priority--p3';
    case 'P4': return 'ops-queue__priority--p4';
    default: return '';
  }
}

/* --- Live Complaint Queue --- */
function LiveQueue() {
  const tabs = ['All', 'P1', 'P2', 'Escalated', 'My queue'];
  const [activeTab, setActiveTab] = useState('All');

  return (
    <div className="ops-queue">
      <div className="ops-queue__header">
        <div>
          <h3 className="ops-queue__title">Live complaint queue</h3>
          <p className="ops-queue__subtitle">Sorted by SLA risk. Unassigned cases first — assign or escalate.</p>
        </div>
        <span className="ops-queue__badge">212 awaiting assignment</span>
      </div>

      <div className="ops-queue__filters">
        <div className="ops-queue__tabs">
          {tabs.map((tab) => (
            <button
              key={tab}
              className={`ops-queue__tab ${activeTab === tab ? 'ops-queue__tab--active' : ''}`}
              onClick={() => setActiveTab(tab)}
            >
              {tab}
            </button>
          ))}
        </div>
        <div className="ops-queue__legend">
          <span className="ops-queue__legend-label">Age colour:</span>
          <span className="ops-queue__legend-fresh">fresh</span>
          <span className="ops-queue__legend-sep"> · </span>
          <span className="ops-queue__legend-risk">SLA risk</span>
          <span className="ops-queue__legend-sep"> · </span>
          <span className="ops-queue__legend-overdue">overdue</span>
        </div>
      </div>

      <table className="ops-queue__table">
        <thead>
          <tr>
            <th>COMPLAINT</th>
            <th>STORE</th>
            <th>PRIORITY</th>
            <th>ASSIGNED AGENT</th>
            <th>STATUS</th>
            <th>AGE</th>
          </tr>
        </thead>
        <tbody>
          {QUEUE_DATA.map((row) => (
            <tr key={row.id}>
              <td>
                <div className="ops-queue__complaint-id">{row.id}</div>
                <div className="ops-queue__complaint-desc">{row.description}</div>
              </td>
              <td>
                <a
                  className="ops-queue__store-name"
                  href={`/x_2145749_qc_dark_store_dashboard.do?store=${row.storeId}`}
                >
                  {row.storeName}
                </a>
                <div className="ops-queue__store-id">{row.storeId}</div>
              </td>
              <td>
                <span className={`ops-queue__priority ${getPriorityClass(row.priority)}`}>
                  {row.priority}
                </span>
              </td>
              <td>
                {row.agent === 'Unassigned' ? (
                  <span className="ops-queue__agent--unassigned">Unassigned</span>
                ) : (
                  <span className="ops-queue__agent--assigned">{row.agent} ({row.agentId})</span>
                )}
              </td>
              <td>
                <span className="ops-queue__status">{row.status}</span>
              </td>
              <td>
                <span className={getAgeClass(row.ageMinutes)}>{row.age}</span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

/* --- Main Operations Dashboard --- */
function OpsApp() {
  return (
    <div className="ops-dashboard">
      <NavHeader />
      <div className="ops-dashboard__content">
        <OpsPageHeader />
        <KpiRow />
        <div className="ops-charts-row">
          <PriorityDonutChart />
          <PendingStatusChart />
          <AgentWorkloadChart />
        </div>
        <LiveQueue />
      </div>
    </div>
  );
}

export default OpsApp;
","/* --- Operations Dashboard — Dark Theme --- */

/* --- Dashboard Shell --- */
.ops-dashboard {
  min-height: 100vh;
  background: #0a0e14;
  color: #e2e8f0;
  font-family: -apple-system, BlinkMacSystemFont, 'Inter', 'Segoe UI', sans-serif;
}

.ops-dashboard__content {
  padding: 24px;
  max-width: 1440px;
  margin: 0 auto;
}

/* --- Page Header --- */
.ops-page-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 24px;
}

.ops-page-header__title {
  font-size: 28px;
  font-weight: 700;
  margin: 0 0 4px 0;
  color: #e2e8f0;
}

.ops-page-header__subtitle {
  font-size: 14px;
  color: #64748b;
  margin: 0;
}

.ops-page-header__live-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #94a3b8;
  background: rgba(34, 197, 94, 0.06);
  border: 1px solid rgba(34, 197, 94, 0.2);
  border-radius: 20px;
  padding: 5px 14px;
}

.ops-page-header__live-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #22c55e;
  animation: ops-pulse-glow 2s infinite;
}

@keyframes ops-pulse-glow {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
}

/* --- KPI Row --- */
.ops-kpi-row {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}

/* --- KPI Card --- */
.ops-kpi-card {
  background: #111621;
  border: 1px solid #1a2035;
  border-radius: 12px;
  padding: 20px;
  display: flex;
  flex-direction: column;
}

.ops-kpi-card--red {
  background: rgba(239, 68, 68, 0.04);
  border-color: rgba(239, 68, 68, 0.25);
}

.ops-kpi-card__label {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 600;
  color: #64748b;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  margin-bottom: 12px;
}

.ops-kpi-card__label-icon {
  display: inline-flex;
  color: #ef4444;
}

.ops-kpi-card__value {
  font-size: 28px;
  font-weight: 700;
  color: #e2e8f0;
  font-variant-numeric: tabular-nums;
  margin-bottom: auto;
  padding-bottom: 12px;
}

.ops-kpi-card__value--red {
  color: #ef4444;
}

.ops-kpi-card__caption {
  font-size: 11px;
  color: #64748b;
  margin: 0;
  line-height: 1.5;
}

/* --- Charts Row --- */
.ops-charts-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  margin-bottom: 24px;
}

/* --- Generic Card --- */
.ops-card {
  background: #111621;
  border: 1px solid #1a2035;
  border-radius: 12px;
  padding: 24px;
}

.ops-card__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 20px;
}

.ops-card__title {
  font-size: 15px;
  font-weight: 600;
  color: #e2e8f0;
  margin: 0 0 4px 0;
}

.ops-card__subtitle {
  font-size: 12px;
  color: #64748b;
  margin: 0;
}

/* --- Donut Chart --- */
.ops-donut {
  display: flex;
  align-items: center;
  gap: 24px;
}

.ops-donut__legend {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.ops-donut__legend-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: #94a3b8;
}

.ops-donut__legend-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}

.ops-donut__legend-value {
  color: #64748b;
  margin-left: 4px;
}

/* --- Horizontal Bar Chart --- */
.ops-hbar {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.ops-hbar__row {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ops-hbar__label {
  font-size: 11px;
  color: #94a3b8;
  width: 110px;
  flex-shrink: 0;
  text-align: right;
}

.ops-hbar__track {
  flex: 1;
  height: 18px;
  background: rgba(59, 130, 246, 0.06);
  border-radius: 3px;
  position: relative;
}

.ops-hbar__fill {
  height: 100%;
  background: #3b82f6;
  border-radius: 3px;
  transition: width 0.3s ease;
}

.ops-hbar__value {
  font-size: 10px;
  color: #64748b;
  width: 32px;
  text-align: right;
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}

.ops-hbar__axis {
  display: flex;
  justify-content: space-between;
  padding-left: 122px;
  padding-right: 44px;
  margin-top: 6px;
}

.ops-hbar__axis-label {
  font-size: 10px;
  color: #475569;
}

/* --- Vertical Bar Chart --- */
.ops-vbar {
  display: flex;
  gap: 8px;
  height: 200px;
}

.ops-vbar__y-axis {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 0 4px 24px 0;
}

.ops-vbar__y-label {
  font-size: 10px;
  color: #475569;
  text-align: right;
  width: 28px;
}

.ops-vbar__bars {
  display: flex;
  flex: 1;
  align-items: flex-end;
  gap: 12px;
  padding-bottom: 24px;
  border-bottom: 1px solid #1a2035;
}

.ops-vbar__col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
}

.ops-vbar__bar-wrap {
  flex: 1;
  width: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.ops-vbar__bar {
  width: 60%;
  background: #3b82f6;
  border-radius: 3px 3px 0 0;
  min-height: 4px;
  transition: background 0.12s ease;
}

.ops-vbar__bar:hover {
  background: #60a5fa;
}

.ops-vbar__x-label {
  font-size: 9px;
  color: #475569;
  margin-top: 8px;
  text-align: center;
  white-space: nowrap;
}

/* --- Live Queue Section --- */
.ops-queue {
  background: #111621;
  border: 1px solid #1a2035;
  border-radius: 12px;
  padding: 24px;
}

.ops-queue__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 16px;
}

.ops-queue__title {
  font-size: 15px;
  font-weight: 600;
  color: #e2e8f0;
  margin: 0 0 4px 0;
}

.ops-queue__subtitle {
  font-size: 12px;
  color: #64748b;
  margin: 0;
}

.ops-queue__badge {
  font-size: 11px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 6px;
  color: #f59e0b;
  background: rgba(245, 158, 11, 0.08);
  border: 1px solid rgba(245, 158, 11, 0.2);
  white-space: nowrap;
  flex-shrink: 0;
}

/* --- Filter Tabs --- */
.ops-queue__filters {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 16px;
  border-bottom: 1px solid #1a2035;
  padding-bottom: 12px;
}

.ops-queue__tabs {
  display: flex;
  gap: 4px;
}

.ops-queue__tab {
  font-size: 12px;
  font-weight: 500;
  color: #64748b;
  background: none;
  border: none;
  padding: 6px 14px;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.12s ease, color 0.12s ease;
}

.ops-queue__tab:hover {
  background: rgba(255, 255, 255, 0.04);
  color: #94a3b8;
}

.ops-queue__tab--active {
  background: rgba(59, 130, 246, 0.1);
  color: #3b82f6;
  font-weight: 600;
}

.ops-queue__legend {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  color: #64748b;
}

.ops-queue__legend-label {
  color: #64748b;
  margin-right: 4px;
}

.ops-queue__legend-fresh {
  color: #22c55e;
}

.ops-queue__legend-sep {
  color: #64748b;
  margin: 0 2px;
}

.ops-queue__legend-risk {
  color: #f59e0b;
}

.ops-queue__legend-overdue {
  color: #ef4444;
}

/* --- Table --- */
.ops-queue__table {
  width: 100%;
  border-collapse: collapse;
}

.ops-queue__table thead th {
  font-size: 10px;
  font-weight: 600;
  color: #475569;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  text-align: left;
  padding: 8px 12px;
  border-bottom: 1px solid #1a2035;
}

.ops-queue__table tbody tr {
  border-bottom: 1px solid rgba(26, 32, 53, 0.5);
  transition: background 0.1s ease;
}

.ops-queue__table tbody tr:hover {
  background: rgba(255, 255, 255, 0.02);
}

.ops-queue__table tbody td {
  padding: 10px 12px;
  font-size: 13px;
  vertical-align: top;
}

/* --- Table Cells --- */
.ops-queue__complaint-id {
  font-weight: 600;
  color: #e2e8f0;
  font-size: 12px;
}

.ops-queue__complaint-desc {
  font-size: 11px;
  color: #64748b;
  margin: 2px 0 0 0;
}

.ops-queue__store-name {
  color: #3b82f6;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  text-decoration: none;
}

.ops-queue__store-name:hover {
  text-decoration: underline;
}

.ops-queue__store-id {
  font-size: 11px;
  color: #64748b;
  margin: 2px 0 0 0;
}

/* --- Priority Badges --- */
.ops-queue__priority {
  display: inline-flex;
  align-items: center;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
}

.ops-queue__priority--p1 {
  color: #ef4444;
  background: rgba(239, 68, 68, 0.1);
  border: 1px solid rgba(239, 68, 68, 0.25);
}

.ops-queue__priority--p2 {
  color: #f59e0b;
  background: rgba(245, 158, 11, 0.1);
  border: 1px solid rgba(245, 158, 11, 0.25);
}

.ops-queue__priority--p3 {
  color: #64748b;
  background: rgba(59, 130, 246, 0.08);
  border: 1px solid rgba(59, 130, 246, 0.2);
}

.ops-queue__priority--p4 {
  color: #64748b;
  background: rgba(100, 116, 139, 0.1);
  border: 1px solid rgba(100, 116, 139, 0.2);
}

/* --- Agent --- */
.ops-queue__agent--unassigned {
  color: #f59e0b;
  font-weight: 500;
}

.ops-queue__agent--assigned {
  color: #94a3b8;
}

/* --- Status --- */
.ops-queue__status {
  font-size: 12px;
  color: #94a3b8;
}

/* --- Age Colors --- */
.ops-queue__age--fresh {
  color: #22c55e;
  font-variant-numeric: tabular-nums;
}

.ops-queue__age--risk {
  color: #f59e0b;
  font-variant-numeric: tabular-nums;
}

.ops-queue__age--overdue {
  color: #ef4444;
  font-variant-numeric: tabular-nums;
}

/* --- Responsive --- */
@media (max-width: 1200px) {
  .ops-kpi-row {
    grid-template-columns: repeat(3, 1fr);
  }
  .ops-charts-row {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .ops-kpi-row {
    grid-template-columns: repeat(2, 1fr);
  }
  .ops-page-header {
    flex-direction: column;
    gap: 12px;
  }
  .ops-queue__filters {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
  }
}
